'use strict';
const page=document.body.dataset.page,detail=document.querySelector('#detail'),upload=document.querySelector('#upload');
let urls=[];const clearUrls=()=>{urls.forEach(URL.revokeObjectURL);urls=[]};
document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());detail.addEventListener('close',()=>{const video=detail.querySelector('video');if(video)video.pause();clearUrls()});
const stories={intro:['AI와 함께 만드는 새로운 가능성, 그 시작을 기록하다.','이 글은 페이지 구성을 위한 예시 기사입니다.\n\nAI 교육에서 가장 먼저 배운 것은 도구의 이름이 아니라 질문을 구체화하는 방법이었습니다. 막연한 아이디어를 대상, 목적, 형식으로 나누자 결과물의 방향도 선명해졌습니다.\n\n기사에서는 정보를 구조화하고, 이미지에서는 분위기를 시각화하며, 영상에서는 흐름을 설계했습니다. 같은 주제라도 표현 방식에 따라 전달되는 의미가 달라진다는 것을 경험했습니다.\n\n결과물을 완성하는 일만큼 중요한 것은 과정을 기록하는 일입니다. 이 포트폴리오는 작은 실험과 개선의 흔적을 모으는 공간입니다.'],research:['생성형 AI가 바꾸는 우리의 일하는 방식','교육용 예시 기사 · 리서치\n\n자료의 초안을 정리하거나 아이디어를 비교할 때 AI는 유용한 출발점이 됩니다. 하지만 결과를 그대로 사용하는 대신 근거를 검토하고 목적에 맞게 편집하는 과정이 필요합니다.\n\n이번 실습에서는 같은 주제를 요약, 비교표, 기사 초안으로 요청했습니다. 형식을 구체적으로 정할수록 활용하기 쉬운 결과가 나왔습니다.\n\n다음 실험에서는 실제 업무 과제를 정하고 수정 시간과 결과의 정확성을 함께 기록해 보려고 합니다.'],insight:['좋은 질문이 만드는 더 나은 AI의 답변','교육용 예시 기사 · 인사이트\n\n첫째, 누구를 위한 결과물인지 설명합니다. 독자가 달라지면 필요한 설명과 어휘도 달라집니다.\n\n둘째, 맥락과 참고 자료를 제공합니다. 무엇을 알고 있고 무엇을 더 알아야 하는지 구분하면 답변의 범위가 명확해집니다.\n\n셋째, 길이와 형식을 정합니다. 완성된 답변을 검토하고 부족한 부분을 다시 질문하며 결과물을 다듬습니다.'],learning:['작은 실험에서 시작한 나의 첫 AI 콘텐츠','교육용 예시 기사 · 교육 기록\n\n하나의 문장을 이미지로 바꾸는 것으로 실습을 시작했습니다. 색상과 조명, 구도를 조금씩 바꿔가며 결과의 차이를 비교했습니다.\n\n가장 인상 깊었던 순간은 첫 결과가 아니라 수정 후의 결과였습니다. 구체적인 피드백이 결과물을 바꾼다는 것을 확인했습니다.\n\n다음 작업에서는 프롬프트와 수정 이유를 함께 기록해 나만의 제작 과정을 만들어 가겠습니다.'],film:['브랜드 필름 — 30초 스토리보드','영상 제작 전 기획 예시이며, 재생 가능한 영상은 아직 등록되지 않았습니다.\n\n00–08초 / 질문\n빈 화면에 한 문장의 질문이 등장합니다. “나의 아이디어는 어디까지 갈 수 있을까?”\n\n08–20초 / 실험\n문장, 이미지, 장면으로 아이디어가 확장됩니다. 푸른 리본이 장면을 연결하는 시각 모티프입니다.\n\n20–30초 / 완성\n세 가지 결과물을 한 화면으로 연결합니다. 마지막 메시지는 “배우고, 만들고, 연결하다.”입니다.']};
function show(title,node){document.querySelector('#detail-title').textContent=title;document.querySelector('#detail-body').replaceChildren(node);detail.showModal()}
document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{const s=stories[b.dataset.detail],p=document.createElement('p');p.className='detail-text';p.textContent=s[1];show(s[0],p)});
document.querySelectorAll('[data-art]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.art),box=document.createElement('div'),img=document.createElement('img'),p=document.createElement('p');img.src='assets/ribbon.png';img.alt='푸른 반투명 리본의 추상 이미지';img.style.filter=['none','hue-rotate(45deg)','hue-rotate(290deg)'][i];p.textContent='제작 노트: 옅은 하늘색 배경, 반투명한 푸른 리본, 부드러운 스튜디오 조명. AI 생성 이미지'+(i?'에 색상 변주를 적용했습니다.':'입니다.');box.append(img,p);show(['Blue flow','A different hue','Into the detail'][i],box)});
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});document.querySelectorAll('[data-category]').forEach(c=>c.hidden=b.dataset.filter!=='all'&&c.dataset.category!==b.dataset.filter)});
const allowed={article:['pdf','txt'],image:['jpg','jpeg','png','webp'],video:['mp4','webm'],final:['pdf','zip']};
const category=document.querySelector('#category'),fileInput=document.querySelector('#file'),status=document.querySelector('#status');
function accept(){fileInput.accept=allowed[category.value].map(x=>'.'+x).join(',')}category.onchange=accept;
document.querySelectorAll('[data-upload]').forEach(b=>b.onclick=()=>{category.value=page;accept();status.textContent='';upload.showModal()});
let database;function db(){return database||(database=new Promise((resolve,reject)=>{const r=indexedDB.open('hankyung-ai-portfolio',1);r.onupgradeneeded=()=>r.result.createObjectStore('materials',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)}))}
async function transact(mode,action){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('materials',mode),r=action(t.objectStore('materials'));t.oncomplete=()=>resolve(r.result);t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)})}
async function render(){const records=await transact('readonly',s=>s.getAll());const list=document.querySelector('#local-list');list.replaceChildren();const current=records.filter(r=>r.category===page).sort((a,b)=>b.created-a.created);document.querySelector('#my-materials').hidden=!current.length;for(const r of current){const item=document.createElement('article'),title=document.createElement('h3'),desc=document.createElement('p'),view=document.createElement('button'),del=document.createElement('button');item.className='local-item';title.textContent=r.title;desc.className='notice';desc.textContent=r.description;view.className='text-button';view.textContent='자료 열기 ↗';view.onclick=()=>{const box=document.createElement('div'),url=URL.createObjectURL(r.file);urls.push(url);if(r.category==='image'){const img=document.createElement('img');img.src=url;img.alt=r.title;box.append(img)}else if(r.category==='video'){const v=document.createElement('video');v.src=url;v.controls=true;v.playsInline=true;box.append(v)}const text=document.createElement('p');text.textContent=r.description;const a=document.createElement('a');a.href=url;a.download=r.file.name;a.className='button';a.textContent='파일 다운로드';box.append(text,a);show(r.title,box)};del.className='danger';del.textContent='삭제';del.onclick=async()=>{if(!confirm('이 브라우저에서 해당 자료를 삭제할까요?'))return;try{await transact('readwrite',s=>s.delete(r.id));await render()}catch{alert('자료를 삭제하지 못했습니다. 다시 시도해 주세요.')}};item.append(title,desc,view,del);list.append(item)}}
document.querySelector('#upload-form').onsubmit=async e=>{e.preventDefault();const f=fileInput.files[0],title=document.querySelector('#title').value.trim();if(!title){status.textContent='제목을 입력해 주세요.';return}if(!f||!allowed[category.value].includes(f.name.split('.').pop().toLowerCase())){status.textContent='선택한 분류에 맞는 파일 형식을 선택해 주세요.';return}if(f.size>50*1024*1024){status.textContent='50MB 이하의 파일을 선택해 주세요.';return}const b=e.target.querySelector('[type=submit]');b.disabled=true;try{await transact('readwrite',s=>s.put({id:crypto.randomUUID(),created:Date.now(),category:category.value,title,description:document.querySelector('#description').value,file:f}));const target=category.value;e.target.reset();if(target!==page){location.href=target+'.html#my-materials';return}await render();upload.close();document.querySelector('#my-materials').scrollIntoView({behavior:'smooth'})}catch{status.textContent='저장 공간이 부족하거나 브라우저 저장이 차단되었습니다. 파일 크기와 브라우저 설정을 확인해 주세요.'}finally{b.disabled=false}};
render().catch(()=>{document.querySelectorAll('[data-upload]').forEach(b=>b.onclick=()=>{upload.showModal();status.textContent='이 브라우저에서 저장소를 사용할 수 없습니다. 일반 브라우저에서 페이지를 열어 주세요.'})});
if(document.modelContext?.registerTool){const life=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'list_portfolio_materials',description:'List materials saved in this browser for the current portfolio category.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},async execute(input){if(!input||Object.keys(input).length)throw new Error('No arguments are accepted.');return(await transact('readonly',s=>s.getAll())).filter(r=>r.category===page).map(r=>({title:r.title,description:r.description,filename:r.file.name,category:r.category}))}},{signal:life.signal})).catch(()=>{});addEventListener('pagehide',()=>life.abort(),{once:true})}catch{}}
